from pathlib import Path
p=Path(__file__).parent
rr={'Для масштаба неопределённости: при':'При','незапрошенное; чтение из кэша сюда не входит.':'незапрошенные значения. Поля из кэша учитываются отдельно.','чтения на запрос; 95%-й парный':'чтения на запрос. Для этой разности 95%-й парный','полей; при восьми':'полей. При восьми','дистрибутивы релизов различны;':'дистрибутивы релизов различны.','метаданными. Изолированный':'метаданными. Изолированный','с PyPI; его':'с PyPI. Его','интерфейсом; названия':'интерфейсом. Названия','задаются; фиксировались':'задаются. Фиксировались','задавались; фиксировались':'задавались. Фиксировались','(40 байт); за':'(40 байт). За','состав примеров; формальные':'состав примеров. Формальные'}
for name in ('primary.py','other.py','report.py'):
    f=p/name;s=f.read_text(encoding='utf-8')
    for a,b in rr.items():s=s.replace(a,b)
    f.write_text(s,encoding='utf-8')

